
use axum::{extract::{State, Path}, Json}; use serde::{Deserialize, Serialize}; use crate::core::AppState; use uuid::Uuid;
#[derive(Deserialize, Serialize, validator::Validate)] pub struct CreateObituary { #[validate(length(min=1, max=200))] pub full_name: String, pub date_of_birth: chrono::NaiveDate, pub date_of_passing: chrono::NaiveDate, #[validate(length(max=10000))] pub biography_encrypted: String, pub service_date: Option<chrono::DateTime<chrono::Utc>>, pub visibility: Visibility, }
#[derive(Deserialize, Serialize, sqlx::Type)] #[sqlx(type_name="visibility", rename_all="lowercase")] pub enum Visibility { Public, Private, Unlisted }
pub async fn create(State(s): State<AppState>, Json(payload): Json<CreateObituary>) -> Json<serde_json::Value> { let id = Uuid::new_v4(); sqlx::query!("INSERT INTO obituaries (id, full_name, data) VALUES ($1, $2, $3)", id, payload.full_name, serde_json::to_value(&payload).unwrap()).execute(&s.db).await.unwrap(); s.nats.publish("obituary.created".into(), id.to_string().into()).await.unwrap(); Json(serde_json::json!({"id": id})) }
pub async fn list(State(s): State<AppState>) -> Json<Vec<serde_json::Value>> { let rows = sqlx::query!("SELECT data FROM obituaries ORDER BY created_at DESC LIMIT 100").fetch_all(&s.db).await.unwrap(); Json(rows.into_iter().map(|r| r.data).collect()) }
pub async fn get(State(s): State<AppState>, Path(id): Path<Uuid>) -> Json<serde_json::Value> { let row = sqlx::query!("SELECT data FROM obituaries WHERE id=$1", id).fetch_one(&s.db).await.unwrap(); Json(row.data) }
pub async fn update(State(s): State<AppState>, Path(id): Path<Uuid>, Json(p): Json<CreateObituary>) -> Json<serde_json::Value> { sqlx::query!("UPDATE obituaries SET data=$2, updated_at=NOW() WHERE id=$1", id, serde_json::to_value(&p).unwrap()).execute(&s.db).await.unwrap(); Json(serde_json::json!({"ok": true})) }
